function composer(){return `<div class="composer-zone"><form class="composer" data-composer><textarea aria-label="Message your Tender Manager" rows="2" placeholder="Ask your Manager, or add a constraint…">${esc(state.draft)}</textarea><div class="composer-tools"><button class="icon-button" type="button" data-action="documents" aria-label="View example attachments">${icon('attachment')}</button><span>Preview only · no AI request</span><button class="send-button" type="submit" aria-label="Send example message">${icon('arrow')}</button></div></form><p class="composer-hint">Your instructions stay with this tender.</p></div>`;}
