 const messages=demoMessages.filter(m=>m.step<=state.event&&(state.all||m.important));
 q('#office-layout').innerHTML=`<section class="office-map" aria-label="Example shared work area"><div class="manager-anchor">${avatar('manager')}<div><strong>${esc(state.managerName)}<span class="ai-label">AI</span></strong><small>Plans the work · coordinates the team</small></div></div>${staff.length?`<div class="team-grid" style="grid-template-columns:repeat(${Math.min(staff.length,3)},minmax(0,1fr))">${staff.map(s=>{const [label,tone,ic]=staffStatus(s);return `<button class="staff-card ${newId===s.id?'arriving':''}" data-staff="${s.id}" aria-label="Open ${s.name} staff desk">${avatar(s.id)}<h3>${s.name}</h3><p class="staff-role">${s.role}</p><span class="tag ${tone}">${icon(ic)}${label}</span><p class="staff-task">${s.task}</p><span class="open-desk">Open staff desk${icon('arrow')}</span></button>`;}).join('')}</div><div class="handoff-line ${newId?'flash':''}">${icon(state.event>=7?'check':'arrow')}<span>${eventLabels[state.event]}</span></div><p class="map-note">${icon('info')}<span>These are example profiles for this task. In the application, the Manager will generate each complete profile as needed.</span></p>`:`<div class="empty-team"><h3>The team starts with your request.</h3><p>No specialists are pre-created. Play the example to see the Manager form a team and share the work.</p><button class="button primary" data-action="play">${icon('play')}Play example</button></div>`}</section><section class="office-discussion" aria-label="Office conversation"><div class="discussion-heading"><h3>Office conversation</h3><div class="segmented" aria-label="Conversation visibility"><button data-filter="highlights" aria-pressed="${!state.all}">Highlights</button><button data-filter="all" aria-pressed="${state.all}">All exchanges</button></div></div><div class="office-messages">${messages.length?messages.map(m=>`<div class="office-message">${avatar(m.from)}<div class="office-message-body"><div class="office-message-header"><strong>${m.from==='manager'?esc(state.managerName):demoStaff.find(s=>s.id===m.from).name}</strong><small>Step ${m.step}</small></div><div class="message-recipient">To ${esc(m.to)}</div><p>${m.text}</p>${m.artifact?`<button class="message-artifact" data-artifact="${esc(m.artifact)}">${icon('files')}${m.artifact}${icon('arrow')}</button>`:''}</div></div>`).join(''):'<p class="discussion-empty">The example exchanges will appear here as the team forms.</p>'}</div></section>`;
 const thread=q('.office-messages'); if(oldThread)thread.scrollTop=wasAtEnd?thread.scrollHeight:oldScroll; q('.office-map').scrollTop=oldMapScroll;
