function showOffice(){renderOffice();q('#office-dialog').showModal();}
function stopPlay(){clearInterval(playTimer);state.playing=false;}
function setStage(stage){stopPlay();state.stage=stage;state.event=stage===0?0:stage===1?5:7;renderBody();if(q('#office-dialog').open)renderOffice();}
function nextEvent(){if(state.event>=7){stopPlay();return;}state.event++;state.stage=state.event>=7?2:1;const created=demoStaff.find(s=>s.created===state.event);renderBody();renderOffice(created?.id);if(state.event>=7){stopPlay();renderOffice();}}
function togglePlay(){if(state.playing){stopPlay();renderOffice();return;}if(state.event>=7){state.event=0;state.stage=0;state.reviewed=false;state.decisions=[];state.decisionDraft=[];renderBody();}state.playing=true;renderOffice();nextEvent();if(state.event<7)playTimer=setInterval(nextEvent,1200);}
function toast(message){clearTimeout(toastTimer);q('#toast').textContent=message;q('#toast').classList.add('visible');toastTimer=setTimeout(()=>q('#toast').classList.remove('visible'),4000);}
function detail(title,body,footer=''){
 const dialog=q('#detail-dialog');
 if(dialog.open && q('#detail-title')?.textContent!==title){
   dialog.querySelectorAll('input[type=checkbox]').forEach(input=>input.toggleAttribute('checked',input.checked));
   detailStack.push({html:q('#detail-content').innerHTML,scroll:dialog.scrollTop});
 }
 q('#detail-content').innerHTML=`<div class="dialog-top"><div>${detailStack.length?'<button class="text-button" data-action="back-detail" style="font-size:11px;margin-bottom:8px">Return to previous view</button>':''}<h2 id="detail-title">${title}</h2></div><button class="icon-button" data-close="detail-dialog" aria-label="Close detail">${icon('close')}</button></div><div class="detail-body">${body}</div>${footer?`<div class="dialog-bottom">${footer}</div>`:''}`;if(!q('#detail-dialog').open)q('#detail-dialog').showModal();}
