function source(){detail('Source evidence',`<span class="tag green">Synthetic source</span><div class="profile-section" style="border:0;margin-top:0"><h3>A-104 · General arrangement · Rev B</h3><p>Detail 2 · highlighted positions D-14 and D-21</p>${drawing(true)}</div><table class="comparison-table"><thead><tr><th>Source</th><th>What the example establishes</th></tr></thead><tbody><tr><td>Drawing · D-14</td><td>Door location and reference. Rating requires clarification.</td></tr><tr><td>Schedule · D-21</td><td>Different quantity basis from BOQ A/12.</td></tr><tr><td>BOQ · A/12</td><td>Original quantity retained pending the engineer’s decision.</td></tr></tbody></table><p class="document-footnote">This schematic and its references are authored synthetic examples. They are not extracted Tender evidence or a verified takeoff.</p>`,`<span class="muted">Original basis remains visible</span><button class="button secondary small" data-action="history">View source register${icon('arrow')}</button>`);}
function documents(){detail('Example document register',`<p class="inline-notice">Three synthetic files support this UI journey. No customer files are loaded.</p><div class="doc-list">${[['A-104 · General arrangement','Rev B · example drawing'],['Door schedule','Rev C · example schedule'],['Architectural BOQ','Section A/12 · example workbook']].map(d=>`<button data-action="source">${icon('files')}<span><strong>${d[0]}</strong><small>${d[1]}</small></span>${icon('arrow')}</button>`).join('')}</div>`,`<span class="muted">All content is illustrative</span><button class="button secondary small" data-close="detail-dialog">Return to workspace</button>`);}
function decisions(){detail('Two questions for your decision',`<p class="profile-summary">The example team has checked the references. Choose a direction for the clarification draft.</p><div class="decision-option"><label><input type="checkbox" name="decision" value="rating" ${state.decisionDraft.includes('rating')?'checked':''}><span><strong>D-14 · Clarify the fire rating</strong><br>Ask which requirement governs before changing the specification.</span></label><small>Proposed next action: prepare a clarification question.</small><button class="source-link" data-action="source">${icon('files')}View the drawing and schedule</button></div><div class="decision-option"><label><input type="checkbox" name="decision" value="quantity" ${state.decisionDraft.includes('quantity')?'checked':''}><span><strong>D-21 · Retain the BOQ quantity for now</strong><br>Raise the schedule difference for confirmation.</span></label><small>Original BOQ retained. No accepted quantity is changed.</small><button class="source-link" data-action="source">${icon('files')}View the comparison basis</button></div><p class="field-note" style="margin-top:18px">This action changes only this synthetic preview. It sends nothing and approves no real Tender.</p>`,`<span class="muted">No commercial sending</span><button class="button primary" data-action="save-decision">Save demo decision${icon('check')}</button>`);}
function plan(){detail('Review the example work plan',`<p class="profile-summary">Compare the revised drawing package and prepare the material questions for the engineer.</p><dl class="profile-fields"><dt>Source scope</dt><dd>The three synthetic documents in this concept.</dd><dt>Work</dt><dd>Trace revisions, compare affected door items, and independently check the evidence.</dd><dt>Staffing</dt><dd>The Manager forms the example team as the work needs it. No specialists exist in the opening state.</dd><dt>Output</dt><dd>A source-linked revision review and clarification questions.</dd><dt>Authority</dt><dd>Prepare drafts. Retain the original BOQ. No external sending.</dd></dl><div class="note-line">${icon('info')}<span>This interactive concept makes no AI requests and incurs no model spending.</span></div>`,`<span class="muted">Synthetic plan · preview only</span><button class="button primary" data-action="start-example">Start example work${icon('arrow')}</button>`);}
function about(){detail('About this interactive concept',`<p class="profile-summary">Explore the approved Quantix office design through three connected states.</p><ol class="about-list"><li><strong>Manager alone:</strong> review the example plan or customize your Manager.</li><li><strong>Team at work:</strong> expand the office, play the example, inspect a colleague and follow a handoff.</li><li><strong>Ready to review:</strong> open source evidence and record a demo decision.</li></ol><div class="profile-section"><h3>What is real in this preview</h3><p>Navigation, state changes, profile editing, theme switching, motion controls, source inspection and demo decisions work locally. People, messages and sources are synthetic fixtures. No model runs, customer files, real approvals or backend connection are used.</p></div><div class="profile-section"><h3>What belongs to application implementation</h3><p>Live staff generation, private contexts, actual tool execution, durable office events and close-to-tray background work will be implemented and verified separately. Closing this browser tab is not a preview of native tray behavior.</p></div>`,`<span class="muted">Concept for review · application unchanged</span><button class="button secondary small" data-close="detail-dialog">Explore the concept${icon('arrow')}</button>`);}
function openSettings(){detail('Preview preferences',`<div class="doc-list"><button data-action="customize">${icon('sliders')}<span><strong>Manager personality</strong><small>Name, working style and explanation preference</small></span>${icon('arrow')}</button><button data-action="theme">${icon('moon')}<span><strong>Appearance</strong><small>Currently ${document.documentElement.dataset.theme}; click to switch</small></span>${icon('arrow')}</button><button data-action="motion">${icon('play')}<span><strong>Motion</strong><small>${state.reduced?'Reduced':'Full'} motion; system reduced-motion preference is always respected</small></span>${icon('arrow')}</button></div><p class="field-note" style="margin-top:18px">Changes apply only to this browser preview.</p>`);}
function handleAction(action){
 if(action==='back-detail'){const previous=detailStack.pop();if(previous){q('#detail-content').innerHTML=previous.html;q('#detail-dialog').scrollTop=previous.scroll;}return;}

 if(action==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';syncHeader();if(q('#detail-dialog').open&&q('#detail-title')?.textContent==='Preview preferences')openSettings();return;}
 if(action==='motion'){state.reduced=!state.reduced;document.documentElement.dataset.motion=state.reduced?'reduced':'full';renderOffice();toast(state.reduced?'Reduced motion enabled for this preview.':'Full motion enabled; system preferences are still respected.');if(q('#detail-dialog').open&&q('#detail-title')?.textContent==='Preview preferences')openSettings();return;}
 if(action==='office'){if(!q('#office-dialog').open)showOffice();return;}
 if(action==='return-office'){q('#detail-dialog').close();if(!q('#office-dialog').open)showOffice();return;}
 if(action==='play'){togglePlay();return;}
 if(action==='next-event'){stopPlay();if(state.event===7){toast('The example is complete. Replay it to see the team form again.');return;}nextEvent();return;}
 if(action==='manager'){q('#office-dialog').close();q('#detail-dialog').close();return;}
 if(action==='documents'||action==='history'){documents();return;}
 if(action==='source'){source();return;}
 if(action==='decisions'){decisions();return;}
 if(action==='plan'){plan();return;}
 if(action==='start-example'){q('#detail-dialog').close();state.stage=0;state.event=0;state.reviewed=false;state.decisions=[];state.decisionDraft=[];renderBody();if(!q('#office-dialog').open)showOffice();togglePlay();return;}
 if(action==='save-decision'){const checked=[...document.querySelectorAll('input[name=decision]:checked')];if(!checked.length){toast('Select at least one direction for this demo decision.');return;}state.decisions=checked.map(x=>x.value);state.decisionDraft=[...state.decisions];state.reviewed=true;state.stage=2;state.event=7;stopPlay();q('#detail-dialog').close();renderBody();if(q('#office-dialog').open)renderOffice();toast('Demo decision recorded in this preview only. Nothing was sent.');return;}
 if(action==='customize'){q('#detail-dialog').close();q('#manager-name').value=state.managerName;q('#manager-style').value=state.style;q('#manager-depth').value=state.depth;if(!q('#customize-dialog').open)q('#customize-dialog').showModal();return;}
 if(action==='settings'){openSettings();return;}
 if(action==='about'){about();return;}
 if(action==='project'){detail('Example Tender workspace',`<p class="profile-summary">West Bay School</p><dl class="profile-fields"><dt>Package</dt><dd>Architectural revisions</dd><dt>Current example</dt><dd>Drawing and door schedule review</dd><dt>People and data</dt><dd>Entirely synthetic, prepared for UI review.</dd><dt>Application scope</dt><dd>Desktop and text first. Only the Tender Manager exists by default.</dd></dl>`);return;}
 if(action==='estimate'){detail('Estimate basis',`<p class="profile-summary">The supplied BOQ remains the starting point.</p><table class="comparison-table"><thead><tr><th>Item</th><th>Working status</th><th>Accepted basis</th></tr></thead><tbody><tr><td>D-14</td>Rating clarification proposed</td>Original BOQ</td></tr><tr><td>D-21</td>Quantity confirmation proposed</td>Original BOQ</td></tr></tbody></table><p class="field-note">This concept demonstrates review and evidence handling. No market rates or real estimate totals are provided.</p>`,`<span class="muted">Synthetic example</span><button class="button secondary small" data-action="source">Inspect source basis${icon('arrow')}</button>`);return;}
 if(action==='submission'){detail('Prepared work',state.stage===2?`<p class="profile-summary">The revision review is ready as a draft.</p><div class="doc-list"><button data-action="decisions">${icon('files')}<span><strong>Revision review · draft 1</strong><small>Two questions and their source references</small></span>${icon('arrow')}</button></div><p class="field-note" style="margin-top:16px">Draft preparation, engineering acceptance and submission release remain separate.</p>`:`<p class="profile-summary">The example has no completed output yet.</p><p class="field-note">Run the example review or choose “Ready to review” in the preview controls to inspect its draft.</p>`,state.stage===2?'':`<span class="muted">No fabricated deliverables</span><button class="button primary" data-action="plan">Review example plan${icon('arrow')}</button>`);return;}
}
document.addEventListener('click',e=>{
 const stage=e.target.closest('[data-stage]');if(stage){setStage(Number(stage.dataset.stage));return;}
 const close=e.target.closest('[data-close]');if(close){q('#'+close.dataset.close).close();return;}
 const artifact=e.target.closest('[data-artifact]');if(artifact){
 const title=artifact.dataset.artifact;
 const records={
  'Revision comparison · draft 1':{intro:'The source references are matched. The affected schedule entries are ready for a separate scope comparison.',headers:['Source','Revision review'],rows:[['A-104 · Rev B','Drawing identifier and detail references matched.'],['Door schedule · Rev C','D-14 and D-21 passed for scope comparison.'],['BOQ · A/12','Original basis preserved for the next check.']]},
  'Door item comparison · draft 1':{intro:'The scope comparison identifies two questions; it does not accept a new quantity or fire rating.',headers:['Item','Scope finding'],rows:[['D-14','Fire-rating references require clarification.'],['D-21','Schedule quantity differs from the supplied BOQ.']]},
  'Evidence check · draft 1':{intro:'The independent example review checked the original references supporting the two questions.',headers:['Check','Recorded outcome'],rows:[['Source basis','Drawing, schedule and BOQ references inspected.'],['D-14 / D-21','Both clarification questions are supported.'],['Authority','No quantity or specification accepted.']]}
 };
 const record=records[title];
 detail(esc(title),`<span class="tag green">Synthetic draft artifact</span><p class="profile-summary">${record.intro}</p><table class="comparison-table"><thead><tr>${record.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${record.rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table><button class="source-link" data-action="source">${icon('files')}Inspect the underlying source evidence</button>`,`<span class="muted">Exact example artifact · draft 1</span><button class="button secondary small" data-close="detail-dialog">Return to office</button>`);return;
 }
 const staff=e.target.closest('[data-staff]');if(staff){openStaff(staff.dataset.staff);return;}
 const filter=e.target.closest('[data-filter]');if(filter){state.all=filter.dataset.filter==='all';renderOffice();return;}
 const action=e.target.closest('[data-action]');if(action){e.preventDefault();handleAction(action.dataset.action);}
});
document.addEventListener('change',e=>{if(e.target.matches('input[name=decision]'))state.decisionDraft=[...document.querySelectorAll('input[name=decision]:checked')].map(x=>x.value);});
document.addEventListener('input',e=>{if(e.target.matches('[data-composer] textarea'))state.draft=e.target.value;});
document.addEventListener('submit',e=>{
 if(e.target.matches('[data-composer]')){e.preventDefault();const content=e.target.querySelector('textarea').value.trim();if(!content){toast('Enter an example message, or use “Review the example plan”.');return;}state.request=content;state.customRequest=content!==originalRequest;state.draft='';plan();}
});
q('#manager-form').addEventListener('submit',e=>{e.preventDefault();const name=q('#manager-name').value.trim();if(!name){q('#manager-name').focus();return;}state.managerName=name;state.style=q('#manager-style').value.trim();state.depth=q('#manager-depth').value;q('#customize-dialog').close();renderBody();if(q('#office-dialog').open)renderOffice();toast('Manager preferences applied to this preview.');});
q('#office-dialog').addEventListener('close',()=>{stopPlay();});
q('#detail-dialog').addEventListener('close',()=>{detailStack=[];});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPlay();if(q('#office-dialog').open)renderOffice();}});
document.querySelectorAll('.primary-nav button,.sidebar-footer>button').forEach(b=>b.setAttribute('aria-label',b.textContent.trim()));
injectIcons();renderBody();
